/** Actual Ampharos prints remain unchanged. Explicit synthetic borrowers isolate uncommon timing/target cases. */
public final class GeneratedRuleBatch85Test {
    static final UUID A=new UUID(0,8511),B=new UUID(0,8512),WATCH=new UUID(0,8513);
    static final String BASIC="me4_en_027",MID="me4_en_028",CARD="me4_en_029",ATTACK="flashing-bolt";
    static final List<String> PRINTS=List.of(CARD,"me4_en_090","mebsp_en_075");
    static final CardDatabase DB=BundledRules.loadCardDefinitions();static final CombatCatalog DATA=BundledCombatData.load();
    static void check(boolean b,String s){GeneratedRuleBatch8Test.check(b,s);}
    static void reject(Runnable r){GeneratedRuleBatch8Test.reject(r);}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static CardInstance hand(ServerMatch m,UUID p,String id){return GeneratedRuleBatch13Test.hand(m,p,id);}
    static void atomic(ServerMatch m,Runnable r){var a=m.privateView(A);var b=m.privateView(B);var v=m.clientView(A);var rng=m.randomTranscript();reject(r);check(a.equals(m.privateView(A))&&b.equals(m.privateView(B))&&v.equals(m.clientView(A))&&rng.equals(m.randomTranscript()),"Rejected action changed zones, field or RNG");}
    static CardDefinition synthetic(String id,CardCategory category,TrainerCategory trainer,boolean basic){return new CardDefinition(id,id,category,trainer,"J",Set.of("international"),basic,category==CardCategory.ENERGY,60,Map.of(),EffectSupport.SUPPORTED,null);}
    static AbilityDefinition pulse(){return DATA.pokemon(CARD).orElseThrow().abilities().getFirst();}
    static TrainerProfile helmet(){return PersistentSourceTriggerTest.trainer("TOOL",PersistentSourceTriggerTest.trigger("synthetic-helmet-draw",PersistentSourceTriggerTest.DAMAGE,"{\"type\":\"draw\",\"amount\":2}"));}
    static ServerMatch game(){return game(CARD,false,"NORMAL");}
    static ServerMatch game(String card,boolean copied,String mode){
        UUID owner=copied?B:A;var defs=new ArrayList<CardDefinition>();var profiles=new HashMap<String,PokemonProfile>();
        for(String id:List.of(BASIC,MID,card)){defs.add(DB.find(id).orElseThrow());profiles.put(id,DATA.pokemon(id).orElseThrow());}
        defs.add(synthetic("base",CardCategory.POKEMON,TrainerCategory.NONE,true));
        for(String id:List.of("lightning","wrong"))defs.add(synthetic(id,CardCategory.ENERGY,TrainerCategory.NONE,false));
        for(String id:List.of("boost","helmet","draw"))defs.add(synthetic(id,CardCategory.TRAINER,id.equals("draw")?TrainerCategory.ITEM:TrainerCategory.TOOL,false));
        boolean weak=mode.contains("WEAK"),resist=mode.contains("RESIST");
        profiles.put("base",new PokemonProfile(2000,1,null,weak?EnergyType.LIGHTNING:null,weak?2:0,resist?EnergyType.LIGHTNING:null,resist?30:0,1,List.of(GeneratedRuleBatch8Test.hit(10,false),CopyAttackTest.copier()),List.of(),EnergyType.COLORLESS));
        var trainers=Map.of("boost",DynamicPassiveModifierTest.trainer("TOOL","{\"type\":\"attack_damage_modifier\",\"direction\":\"DEALT\",\"amount\":30}"),"helmet",helmet(),"draw",ComposedTrainerIntegrationTest.item("{\"type\":\"draw\",\"amount\":2}"));
        var combat=new CombatCatalog(profiles,Map.of("lightning",EnergyType.LIGHTNING,"wrong",EnergyType.FIRE),trainers);
        String[] pool={BASIC,BASIC,BASIC,MID,MID,card,card,"base","base","base","lightning","lightning","wrong","wrong","boost","helmet","draw"};
        for(int seed=0;seed<4000;seed++){
            var decks=new ArrayList<List<CardInstance>>();for(UUID p:List.of(A,B)){var cs=new ArrayList<CardInstance>();for(int i=0;i<60;i++)cs.add(new CardInstance(new UUID(p.getLeastSignificantBits(),i+1),p,pool[i%pool.length]));decks.add(cs);}
            var m=new ServerMatch(A,B,decks.getFirst(),decks.getLast(),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),combat,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);
            if(m.privateView(owner).hand().stream().filter(c->c.definitionId().equals(BASIC)).count()<2||m.privateView(owner).hand().stream().noneMatch(c->c.definitionId().equals("base"))||m.privateView(copied?A:B).hand().stream().filter(c->c.definitionId().equals("base")).count()<2)continue;
            for(UUID p:List.of(A,B)){m.chooseOpeningActive(p,hand(m,p,p.equals(owner)?BASIC:"base").instanceId());if(p.equals(owner))m.placeOpeningBench(p,hand(m,p,BASIC).instanceId());m.placeOpeningBench(p,hand(m,p,"base").instanceId());m.startAfterOpening(p);}
            OpeningTestSupport.complete(m,A,B,0);m.drawCardsByEffect(A,A,24);m.drawCardsByEffect(A,B,24);m.endTurn(A);m.endTurn(B);
            if(List.of(MID,card).stream().anyMatch(id->m.privateView(owner).hand().stream().filter(c->c.definitionId().equals(id)).count()<2)||m.privateView(A).hand().stream().filter(c->c.definitionId().equals("lightning")).count()<2||m.privateView(A).hand().stream().filter(c->c.definitionId().equals("wrong")).count()<2||List.of("boost","draw").stream().anyMatch(id->m.privateView(A).hand().stream().noneMatch(c->c.definitionId().equals(id)))||m.privateView(B).hand().stream().noneMatch(c->c.definitionId().equals("helmet")))continue;
            if(copied)m.endTurn(A);UUID back=m.benchPokemonView(owner).stream().filter(p->p.topCardId().equals(BASIC)).findFirst().orElseThrow().pokemonId();
            m.evolve(owner,active(m,owner),hand(m,owner,MID).instanceId());m.evolve(owner,back,hand(m,owner,MID).instanceId());m.endTurn(owner);m.endTurn(copied?A:B);
            m.evolve(owner,active(m,owner),hand(m,owner,card).instanceId());m.evolve(owner,back,hand(m,owner,card).instanceId());if(copied)m.endTurn(B);return m;
        }throw new AssertionError("No actual Ampharos fixture "+card+"/"+copied+"/"+mode);
    }
    static void attach(ServerMatch m,String id){var c=hand(m,A,id);m.attachEnergyByEffect(A,A,EffectSourceZone.HAND,c.instanceId(),A,active(m,A));}
    static void pay(ServerMatch m){attach(m,"lightning");attach(m,"wrong");}
    static void handSize(ServerMatch m,UUID owner,int n){handSize(m,owner,n,null);}
    /** Public deterministic discard arranges counts; it neither changes card identities nor shuffles. */
    static void handSize(ServerMatch m,UUID owner,int n,String keep){if(m.privateView(owner).hand().size()<n)m.drawCardsByEffect(m.currentPlayer(),owner,n-m.privateView(owner).hand().size());var held=m.privateView(owner).hand();var retain=new LinkedHashSet<UUID>();if(keep!=null){check(n>0,"Kept card needs hand slot");retain.add(hand(m,owner,keep).instanceId());}for(var c:held)if(retain.size()<n)retain.add(c.instanceId());var discard=held.stream().map(CardInstance::instanceId).filter(id->!retain.contains(id)).toList();if(!discard.isEmpty())m.discardHandCardsByEffect(m.currentPlayer(),owner,discard);check(m.privateView(owner).hand().size()==n,"Hand count fixture");}
    static void hands(ServerMatch m,int a,int b){handSize(m,A,a);handSize(m,B,b);}
    static void damage(ServerMatch m,int expected){int old=m.activePokemonView(B).damage();var rng=m.randomTranscript();m.attack(A,ATTACK);check(m.lastAttack().finalDamage()==expected&&m.activePokemonView(B).damage()==old+expected&&m.currentPlayer().equals(B)&&!m.hasPendingEffectChoice()&&m.randomTranscript().equals(rng),"Actual Flashing Bolt damage/turn/choice/RNG expected "+expected);}
    static void roundTrip(ServerMatch m){UUID source=active(m,A);m.switchActiveByEffect(A,A,m.benchPokemonView(A).stream().filter(p->p.topCardId().equals("base")).findFirst().orElseThrow().pokemonId());m.switchActiveByEffect(A,A,source);}
    static void shield(ServerMatch m,String source,String scope){var e=EffectRegistry.standard().parse(JsonParser.parseString(EffectOriginProtectionTest.shield(source,scope,"OPPONENT_ACTIVE","LEAVES_PLAY")).getAsJsonObject());m.executeEffectProgramByRule(A,active(m,A),new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.ON_CARD_PLAYED,List.of(),List.of(e)))),EffectTrigger.ON_CARD_PLAYED);}
    public static void main(String[] args){printedAndEqual();unequalAndLiveActions();scopeAndSuppression();modifiersAndProtection();helmetTiming();costAndCooldown();copiedSource();syntheticBorrowedTiming();syntheticBorrowedScope();privacy();System.out.println("GeneratedRuleBatch85Test passed: all3 actual normal Mareep/Flaaffy/Ampharos evolutions including promo, live equal hands0/1/many220 versus unequal140, SELF no aura/stack, suppression restoration, damage layers/protection, synthetic Helmet reaction timing, LC cost and cooldown clearing/expiry, actual copied donor scope, explicit synthetic borrower before-damage/after-damage/Bench/self/counter/zero scope, private hands");}
    static void printedAndEqual(){for(String id:PRINTS){var c=DB.find(id).orElseThrow();var p=DATA.pokemon(id).orElseThrow();check(c.effectSupport()==EffectSupport.SUPPORTED&&!c.basicPokemon()&&p.hitPoints()==160&&p.pokemonType()==EnergyType.LIGHTNING&&p.weaknessType()==EnergyType.FIGHTING&&p.weaknessMultiplier()==2&&p.resistanceType()==null&&p.retreatCost()==2&&p.prizeCards()==1&&p.evolvesFromName().equals("Flaaffy")&&p.abilities().size()==1&&p.abilities().getFirst().kind()==AbilityDefinition.Kind.PASSIVE,"Printed Ampharos metadata "+id);var a=p.attacks().getFirst();check(p.attacks().size()==1&&a.id().equals(ATTACK)&&a.baseDamage()==140&&a.energyCost().equals(Map.of(EnergyType.LIGHTNING,1,EnergyType.COLORLESS,1))&&a.cannotUseSameAttackDuringNextTurn(),"Printed Flashing Bolt "+id);AttackProgramRules.validate(a);
            for(int n:List.of(0,1,6)){var m=game(id,false,"NORMAL");check(m.activePokemonView(A).evolutionCardIds().equals(List.of(BASIC,MID,id))&&m.benchPokemonView(A).stream().anyMatch(v->v.evolutionCardIds().equals(List.of(BASIC,MID,id))),"Actual named two-stage evolution including alternate promo representative "+id);pay(m);hands(m,n,n);check(!m.canUseAbility(A,active(m,A),p.abilities().getFirst().id()),"Automatic passive offered as activated Ability");damage(m,220);}
        }}
    static void unequalAndLiveActions(){for(int[] counts:new int[][]{{0,1},{1,0},{2,5},{5,2}}){var m=game();pay(m);hands(m,counts[0],counts[1]);damage(m,140);}
        for(boolean becomesEqual:List.of(false,true)){var m=game();pay(m);handSize(m,A,becomesEqual?3:4,"draw");handSize(m,B,4);m.playTrainer(A,hand(m,A,"draw").instanceId(),null);check(m.privateView(A).hand().size()==(becomesEqual?4:5),"Synthetic draw Item net hand change");damage(m,becomesEqual?220:140);}
        var attached=game();pay(attached);handSize(attached,A,4,"lightning");handSize(attached,B,4);attached.attachEnergy(A,hand(attached,A,"lightning").instanceId(),active(attached,A));check(attached.privateView(A).hand().size()==3,"Manual attachment did not change current hand");damage(attached,140);
    }
    static void scopeAndSuppression(){var noAura=game();UUID plain=noAura.benchPokemonView(A).stream().filter(p->p.topCardId().equals("base")).findFirst().orElseThrow().pokemonId();noAura.switchActiveByEffect(A,A,plain);hands(noAura,3,3);noAura.attack(A,"hit");check(noAura.lastAttack().finalDamage()==10&&noAura.activePokemonView(B).damage()==10,"Two Benched Ampharos boosted another attacker");
        var disabled=game();pay(disabled);disabled.disableAbilityEffectsByEffect(A,A,active(disabled,A));hands(disabled,3,3);damage(disabled,140);disabled.endTurn(B);atomic(disabled,()->disabled.attack(A,ATTACK));disabled.endTurn(A);disabled.endTurn(B);hands(disabled,3,3);damage(disabled,220);
    }
    static void modifiersAndProtection(){for(String mode:List.of("NORMAL","WEAK","RESIST","BOOST","BOOST_WEAK","BOOST_RESIST","DAMAGE_GUARD","ATTACK_EFFECT_GUARD","ABILITY_EFFECT_GUARD")){var m=game(CARD,false,mode);pay(m);if(mode.contains("BOOST"))m.playTrainer(A,hand(m,A,"boost").instanceId(),active(m,A));if(mode.equals("DAMAGE_GUARD"))shield(m,"ATTACK","DAMAGE_ONLY");if(mode.equals("ATTACK_EFFECT_GUARD"))shield(m,"ATTACK","EFFECTS_ONLY");if(mode.equals("ABILITY_EFFECT_GUARD"))shield(m,"ABILITY","EFFECTS_ONLY");hands(m,3,3);damage(m,switch(mode){case "WEAK"->440;case "RESIST"->190;case "BOOST"->250;case "BOOST_WEAK"->500;case "DAMAGE_GUARD"->0;default->220;});}}
    static void helmetTiming(){for(boolean equalAtDamage:List.of(false,true)){var m=game();pay(m);m.endTurn(A);m.playTrainer(B,hand(m,B,"helmet").instanceId(),active(m,B));m.endTurn(B);hands(m,equalAtDamage?3:5,3);int before=m.privateView(B).deck().size();damage(m,equalAtDamage?220:140);check(m.privateView(A).hand().size()==(equalAtDamage?3:5)&&m.privateView(B).hand().size()==6&&m.privateView(B).deck().size()==before-3,"Synthetic Helmet must draw2 after damage plus ordinary next-turn draw1");}
    }
    static void costAndCooldown(){var m=game();atomic(m,()->m.attack(A,ATTACK));attach(m,"wrong");attach(m,"wrong");atomic(m,()->m.attack(A,ATTACK));attach(m,"lightning");hands(m,3,3);damage(m,220);m.endTurn(B);check(m.activeAttacks(A).stream().noneMatch(a->a.id().equals(ATTACK)),"Same-name cooldown absent from action list");atomic(m,()->m.attack(A,ATTACK));m.endTurn(A);m.endTurn(B);hands(m,3,3);damage(m,220);
        var cleared=game();pay(cleared);hands(cleared,3,3);damage(cleared,220);cleared.endTurn(B);atomic(cleared,()->cleared.attack(A,ATTACK));roundTrip(cleared);hands(cleared,3,3);damage(cleared,220);
    }
    static void copiedSource(){var m=game(CARD,true,"NORMAL");attach(m,"wrong");hands(m,3,3);var c=m.copyAttackOptions(A,"copy").stream().filter(o->o.attackId().equals(ATTACK)).findFirst().orElseThrow();m.copyAttackWithEnergyDiscards(A,"copy",c.pokemonId(),c.entrySequence(),c.attackId(),List.of(),List.of());check(m.lastAttack().finalDamage()==140&&m.activePokemonView(B).damage()==140&&m.currentPlayer().equals(B),"Copying actual Flashing Bolt copied donor Synchro Pulse or donor's type/cost");m.endTurn(B);check(m.activeAttacks(A).stream().anyMatch(a->a.id().equals("hit")),"Copied same-name cooldown prohibited unrelated attack");m.attack(A,"hit");check(m.lastAttack().finalDamage()==10&&m.activePokemonView(B).damage()==150,"Copied donor passive leaked into later own attack");}
    static AttackDefinition supplied(int base,String extra){return BundledCombatData.attack(JsonParser.parseString("{\"id\":\"supplied\",\"nameZh\":\"Synthetic borrowed attack\",\"energyCost\":{},\"baseDamage\":"+base+",\"damageType\":\"FIRE\",\"effectSupport\":\"SUPPORTED\""+extra+"}").getAsJsonObject(),EffectRegistry.standard());}
    /** Exact real Ability on a synthetic borrower plus synthetic borrow authorization; actual Ampharos data is untouched. */
    static ServerMatch syntheticBorrower(AttackDefinition supplied){
        var grant=BundledCombatData.ability(JsonParser.parseString("{\"id\":\"synthetic-borrow\",\"nameZh\":\"Synthetic borrow permission\",\"kind\":\"PASSIVE\",\"effectSupport\":\"SUPPORTED\",\"triggers\":[{\"trigger\":\"PASSIVE\",\"effects\":[{\"type\":\"borrow_attacks\",\"target\":\"SELF\",\"source_scope\":\"OWN_BENCH\",\"cost_policy\":\"SELECTED_ATTACK\"}]}]}").getAsJsonObject(),EffectRegistry.standard());
        var defs=List.of(synthetic("holder",CardCategory.POKEMON,TrainerCategory.NONE,true),synthetic("provider",CardCategory.POKEMON,TrainerCategory.NONE,true),synthetic("plain",CardCategory.POKEMON,TrainerCategory.NONE,true));
        var plain=new PokemonProfile(1000,0,null,null,0,null,0,1,List.of(GeneratedRuleBatch8Test.hit(10,false)),List.of(),EnergyType.COLORLESS);
        var combat=new CombatCatalog(Map.of("holder",new PokemonProfile(1000,0,null,null,0,null,0,1,List.of(),List.of(pulse(),grant),EnergyType.LIGHTNING),"provider",new PokemonProfile(1000,0,null,null,0,null,0,1,List.of(supplied),List.of(),EnergyType.FIRE),"plain",plain),Map.of());
        for(int seed=0;seed<500;seed++){var decks=new ArrayList<List<CardInstance>>();for(UUID p:List.of(A,B)){String[] ids=p.equals(A)?new String[]{"holder","provider","plain"}:new String[]{"plain"};var cs=new ArrayList<CardInstance>();for(int i=0;i<60;i++)cs.add(new CardInstance(new UUID(p.getLeastSignificantBits(),i+1),p,ids[i%ids.length]));decks.add(cs);}var m=new ServerMatch(A,B,decks.getFirst(),decks.getLast(),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),combat,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);if(List.of("holder","provider").stream().anyMatch(id->m.privateView(A).hand().stream().noneMatch(c->c.definitionId().equals(id))))continue;m.chooseOpeningActive(A,hand(m,A,"holder").instanceId());m.placeOpeningBench(A,hand(m,A,"provider").instanceId());m.chooseOpeningActive(B,hand(m,B,"plain").instanceId());m.placeOpeningBench(B,hand(m,B,"plain").instanceId());m.startAfterOpening(A);m.startAfterOpening(B);OpeningTestSupport.complete(m,A,B,0);m.endTurn(A);m.endTurn(B);return m;}throw new AssertionError("No synthetic borrower");
    }
    static void borrow(ServerMatch m){var o=m.borrowedAttackOptions(A).stream().filter(c->c.holderId().equals(active(m,A))&&c.attackId().equals("supplied")).findFirst().orElseThrow();m.attackBorrowed(A,o.holderId(),o.holderEntry(),o.holderTop(),o.abilityId(),o.providerId(),o.providerEntry(),o.providerTop(),o.attackId(),null,List.of(),List.of(),null,-1,null,null);}
    static void syntheticBorrowedTiming(){for(String mode:List.of("BECOME_EQUAL","BECOME_UNEQUAL","AFTER")){String phase=mode.equals("AFTER")?"AFTER_ATTACK":"BEFORE_ATTACK";int draw=mode.equals("BECOME_UNEQUAL")?1:2;var m=syntheticBorrower(supplied(40,",\"triggers\":[{\"trigger\":\""+phase+"\",\"effects\":[{\"type\":\"draw\",\"amount\":"+draw+"}]}]"));hands(m,3,mode.equals("BECOME_EQUAL")?5:3);borrow(m);check(m.lastAttack().finalDamage()==(mode.equals("BECOME_UNEQUAL")?40:120)&&m.privateView(A).hand().size()==3+draw,"Synchro Pulse used declaration/after-effect hand count instead of damage checkpoint "+mode);}}
    static void syntheticBorrowedScope(){var mixed=syntheticBorrower(supplied(40,",\"damageTarget\":\"ALL_POKEMON\",\"selfDamage\":30,\"triggers\":[{\"trigger\":\"AFTER_ATTACK\",\"effects\":[{\"type\":\"damage_counter\",\"target\":\"OPPONENT_ACTIVE\",\"amount\":2}]}]"));hands(mixed,3,3);borrow(mixed);check(mixed.activePokemonView(B).damage()==140&&mixed.benchPokemonView(B).getFirst().damage()==40&&mixed.activePokemonView(A).damage()==70&&mixed.benchPokemonView(A).getFirst().damage()==40,"Borrowed SELF modifier leaked to opponent Bench/own targets/self damage/counters or lost Active80");
        var zero=syntheticBorrower(supplied(0,",\"triggers\":[{\"trigger\":\"AFTER_ATTACK\",\"effects\":[{\"type\":\"damage_counter\",\"target\":\"OPPONENT_ACTIVE\",\"amount\":2}]}]"));hands(zero,3,3);borrow(zero);check(zero.lastAttack().finalDamage()==0&&zero.activePokemonView(B).damage()==20,"Pulse manufactured damage from zero base or inflated counters");
    }
    static void privacy(){var m=game();pay(m);hands(m,4,4);var s=MatchSession.multiplayer(m,A,B);s.addSpectator(WATCH);var rng=m.randomTranscript();for(UUID viewer:List.of(A,B,WATCH)){var v=s.view(viewer,viewer.equals(WATCH)?null:viewer);check(v.game().effectSelection()==null&&v.game().effectReveal()==null,"Equal-hand passive requested private selection/reveal");var json=new Gson().toJson(v);for(UUID owner:List.of(A,B)){if(!viewer.equals(owner))for(var c:m.privateView(owner).hand())check(!json.contains(c.instanceId().toString()),"Hand identity leaked during passive evaluation");for(var c:m.privateView(owner).deck())check(!json.contains(c.instanceId().toString()),"Deck identity leaked during passive evaluation");}}check(m.randomTranscript().equals(rng),"Reading passive state consumed RNG");damage(m,220);}
}
